    [Theory]
    [InlineData("max-age=0", 2)]
    [InlineData("public, max-age=3600", 1)]
    [InlineData("no-store", 1)]
    [InlineData("max-age=9000000000000000000", 1)]
    [InlineData("max-age=99999999999999999999", 1)]
    public async Task DiscoveryIsReusedOnlyWhileItsMaxAgeHolds(
        string cacheControl,
        int expectedFetches
    )
    {
        /* A max-age of zero expires the cached document at once, so the second
           call fetches it again. A positive max-age, or a header with no
           max-age directive (which falls back to the 24 hour default), reuses
           the cached document. A max-age beyond the one year ceiling, even one
           past the range of a long, is clamped rather than overflowing the
           expiry arithmetic. */
        var client = new CacheControlApiClient(cacheControl);
        var auth = CreateAuthenticator();
        auth.SetApiClient(client);

        await auth.BuildAuthorizationUrlAsync();
        await auth.BuildAuthorizationUrlAsync();

        Assert.Equal(expectedFetches, client.GetRequestCount);
    }

    private sealed class CacheControlApiClient(string cacheControl) : IApiClient
    {
        public int GetRequestCount { get; private set; }

        public Task<ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            GetRequestCount++;
            return Task.FromResult(
                new ApiHttpResponse(
                    200,
                    "{\"authorization_endpoint\":\"https://auth.example.com/authorize\","
                        + "\"token_endpoint\":\"https://auth.example.com/token\"}",
                    new Dictionary<string, string> { { "Cache-Control", cacheControl } }
                )
            );
        }
    }

    private sealed class CountingApiClient : IApiClient
    {
        private readonly Queue<ApiHttpResponse> _responses = new();

        public int GetRequestCount { get; private set; }

        public void Enqueue(string body, int statusCode = 200)
        {
            _responses.Enqueue(
                new ApiHttpResponse(statusCode, body, new Dictionary<string, string>())
            );
        }

        public Task<ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            if (method == "GET")
            {
                GetRequestCount++;
            }
            return Task.FromResult(_responses.Dequeue());
        }
    }
